mapper.select:
SELECT sc.id, sc.student_id, sc.course_id, sc.score, sc.term, sc.exam_time, st.name as student_name, st.student_no, co.course_name, co.credit, st.class_id, cl.class_name FROM scores sc JOIN students st ON sc.student_id = st.id JOIN courses co ON sc.course_id = co.id LEFT JOIN classes cl ON st.class_id = cl.id
AND st.class_id = #{classId}
AND sc.term = #{term}
ORDER BY st.id, co.id, sc.exam_time DESC
